const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions
    const aoi = ee.Geometry.Polygon([
      [-107.40, 33.40],
      [-106.95, 33.40],
      [-106.95, 32.90],
      [-107.40, 32.90],
      [-107.40, 33.40]
    ]);
    const scale = 1000; // per instruction, >=1000 to avoid timeouts
    const date1986 = '1986-06-12';
    const date2020 = '2020-06-09';

    // Helper: scale factors for Landsat Collection 2 L2 SR
    function applyScaleL2(img) {
      const srBands = img.bandNames().filter(ee.Filter.stringStartsWith({leftField: 'item', rightValue: 'SR_B'}));
      const scaled = img.select(srBands).multiply(0.0000275).add(-0.2);
      return img.addBands(scaled, null, true);
    }
    // Helper: cloud/shadow/snow/cirrus mask for L2
    function maskL2(img) {
      const qa = img.select('QA_PIXEL');
      const cloud = qa.bitwiseAnd(1 << 3).neq(0);
      const cloudShadow = qa.bitwiseAnd(1 << 4).neq(0);
      const cirrus = qa.bitwiseAnd(1 << 2).neq(0);
      const snow = qa.bitwiseAnd(1 << 5).neq(0);
      const mask = cloud.or(cloudShadow).or(cirrus).or(snow).not();
      return img.updateMask(mask);
    }
    // Helper: add mNDWI
    function addMNDWI(img, collectionId) {
      const isOLI = collectionId.indexOf('LC08') >= 0 || collectionId.indexOf('LC09') >= 0;
      const green = img.select(isOLI ? 'SR_B3' : 'SR_B2');
      const swir1 = img.select(isOLI ? 'SR_B6' : 'SR_B5');
      const mndwi = green.subtract(swir1).divide(green.add(swir1)).rename('mndwi');
      return img.addBands(mndwi);
    }
    // Helper: count pixels of an image band
    async function countPixels(img, band) {
      const dict = img.select(band).reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      });
      const v = await ee.Dictionary(dict).get(band).getInfo();
      return v || 0;
    }
    // Helper: total pixel count at scale in AOI
    async function totalPixels() {
      const dict = ee.Image(1).rename('c').reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      });
      const v = await ee.Dictionary(dict).get('c').getInfo();
      return v || 0;
    }
    // Helper: compute water area and counts from image with mndwi
    async function waterStats(img, thresh) {
      const m = img.select('mndwi');
      const validCount = await countPixels(m, 'mndwi');
      const totCount = await totalPixels();
      if (totCount === 0) {
        return {valid: 0, total: 0, cloudPct: 100.0, waterCount: 0, waterKm2: 0};
      }
      const cloudPct = 100.0 * (1.0 - (validCount / totCount));
      const water = m.gt(thresh).rename('water').selfMask();
      // count water pixels
      const waterCountDict = water.reduceRegion({
        reducer: ee.Reducer.count(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      });
      let waterCount = await ee.Dictionary(waterCountDict).get('water').getInfo();
      waterCount = waterCount || 0;
      // water area
      const waterAreaDict = ee.Image.pixelArea().updateMask(water).rename('area').reduceRegion({
        reducer: ee.Reducer.sum(),
        geometry: aoi,
        scale: scale,
        maxPixels: 1e9
      });
      let waterAreaM2 = await ee.Dictionary(waterAreaDict).get('area').getInfo();
      waterAreaM2 = waterAreaM2 || 0;
      const waterKm2 = waterAreaM2 / 1e6;
      return {valid: validCount, total: totCount, cloudPct, waterCount, waterKm2};
    }
    // Helper: get collection for sensor and time window
    function getCollection(sensorId, start, end) {
      return ee.ImageCollection(sensorId)
        .filterBounds(aoi)
        .filterDate(start, end)
        .map(applyScaleL2)
        .map(maskL2);
    }
    // Helper: select best image near target date with fallback windows and sensors
    async function selectBest(dateStr, primarySensors, windows) {
      const target = ee.Date(dateStr);
      let chosen = null;
      let meta = null;
      let emptyAll = true;
      for (let w = 0; w < windows.length && !chosen; w++) {
        const win = windows[w];
        const start = ee.Date(dateStr).advance(-win, 'day');
        const end = ee.Date(dateStr).advance(win, 'day');
        for (let s = 0; s < primarySensors.length && !chosen; s++) {
          const sid = primarySensors[s];
          let col = getCollection(sid, start, end);
          const size = await col.size().getInfo();
          if (size === 0) continue;
          emptyAll = false;
          // rank by proximity and cloud cover
          col = col.map(function(im) {
            const diff = ee.Number(im.date().difference(target, 'day')).abs();
            const cc = ee.Number(im.get('CLOUD_COVER')).unmask(50);
            const score = diff.multiply(1000).add(cc);
            return im.set('score', score);
          }).sort('score').limit(5);
          const list = await col.toList(5).getInfo();
          // iterate candidates until we find one with valid pixels
          for (let i = 0; i < list.length; i++) {
            const id = list[i].id;
            let img = ee.Image(id);
            img = addMNDWI(img, sid);
            const valid = await countPixels(img, 'mndwi');
            if (valid > 0) {
              const t = await ee.Date(img.get('system:time_start')).format('YYYY-MM-dd').getInfo();
              chosen = img;
              meta = {sensor: sid.split('/')[1].slice(0,4), date: t, window: win};
              break;
            }
          }
        }
      }
      return {image: chosen, meta, emptyAll};
    }

    // Sensors and windows
    const sensors1986 = ['LANDSAT/LT05/C02/T1_L2', 'LANDSAT/LT04/C02/T1_L2'];
    const sensors2020 = ['LANDSAT/LC08/C02/T1_L2', 'LANDSAT/LE07/C02/T1_L2'];
    const windows = [30, 60]; // days

    // Check empty collections (C1) and select images
    const sel86 = await selectBest(date1986, sensors1986, windows);
    const sel20 = await selectBest(date2020, sensors2020, windows);

    // Report image counts per primary window to satisfy evidence requirement
    async function imagesCountSummary(dateStr, sensors, win) {
      const start = ee.Date(dateStr).advance(-win, 'day');
      const end = ee.Date(dateStr).advance(win, 'day');
      let parts = [];
      for (let s = 0; s < sensors.length; s++) {
        const sid = sensors[s];
        const c = await getCollection(sid, start, end).size().getInfo();
        parts.push(`${sid.split('/')[1].slice(0,4)}:${c}`);
      }
      return parts.join(', ');
    }
    const winRep = 30;
    const count86 = await imagesCountSummary(date1986, sensors1986, winRep);
    const count20 = await imagesCountSummary(date2020, sensors2020, winRep);

    if (sel86.emptyAll || sel20.emptyAll) {
      console.log(`1986 ±${winRep}d Images -> ${count86}`);
      console.log(`2020 ±${winRep}d Images -> ${count20}`);
      console.log('C1: Empty Collection (No images found in date/location for one or both comparison points).');
      console.log('C1');
      return;
    }
    if (!sel86.image) {
      console.log(`1986 ±${winRep}d Images -> ${count86}`);
      console.log('1986: No valid pixels after masking across candidates.');
      console.log('C2');
      return;
    }
    if (!sel20.image) {
      console.log(`2020 ±${winRep}d Images -> ${count20}`);
      console.log('2020: No valid pixels after masking across candidates.');
      console.log('C2');
      return;
    }

    // Compute water stats (mNDWI threshold)
    const thresh = 0.1;
    const st86 = await waterStats(sel86.image, thresh);
    const st20 = await waterStats(sel20.image, thresh);

    // Additional validation for C2
    if (st86.total === 0 || st20.total === 0) {
      console.log('No valid pixels after masking (total=0).');
      console.log('C2');
      return;
    }
    if (st86.valid === 0 || st20.valid === 0) {
      console.log('No valid pixels after masking for one date.');
      console.log('C2');
      return;
    }

    // Validate for C3 (invalid numbers)
    function invalid(v) { return v === null || typeof v === 'undefined' || Number.isNaN(v) || !Number.isFinite(v); }
    if (invalid(st86.waterKm2) || invalid(st20.waterKm2) || st86.waterKm2 < 0 || st20.waterKm2 < 0) {
      console.log('Calculation failure (None/NaN/invalid).');
      console.log('C3');
      return;
    }

    // Print concise evidence (<=20 lines)
    console.log('AOI: Elephant Butte Reservoir, NM (scale=1000m)');
    console.log(`1986 ±${winRep}d Images -> ${count86}`);
    console.log(`1986 chosen -> ${sel86.meta.sensor} ${sel86.meta.date}, validPix:${st86.valid}, cloud%:${st86.cloudPct.toFixed(1)}, water_km2:${st86.waterKm2.toFixed(2)}`);
    console.log(`2020 ±${winRep}d Images -> ${count20}`);
    console.log(`2020 chosen -> ${sel20.meta.sensor} ${sel20.meta.date}, validPix:${st20.valid}, cloud%:${st20.cloudPct.toFixed(1)}, water_km2:${st20.waterKm2.toFixed(2)}`);
    const delta = st20.waterKm2 - st86.waterKm2;
    console.log(`Δ water (2020-1986) km2: ${delta.toFixed(2)}`);

    // Final Answer
    // A: Yes (decrease), B: No (not a decrease)
    if (st20.waterKm2 < st86.waterKm2) {
      console.log('A: Yes');
    } else {
      console.log('B: No');
    }
  } catch (err) {
    console.log('D: Processing error -> ' + (err && err.message ? err.message : err));
    console.log('D');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

